import React, { useEffect, useState } from 'react';
import API from '../api';
import { useLang } from '../LangContext';

export default function News() {
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState(null);
  const { t, lang } = useLang();

  useEffect(() => {
    API.get('/news').then(r => setNews(r.data)).finally(() => setLoading(false));
  }, []);

  // Pick the right language field
  const title = (n) => (lang === 'am' && n.title_am) ? n.title_am : (lang === 'or' && n.title_or) ? n.title_or : n.title;
  const content = (n) => (lang === 'am' && n.content_am) ? n.content_am : (lang === 'or' && n.content_or) ? n.content_or : n.content;

  if (loading) return <div style={{ textAlign: 'center', padding: 80, color: '#a3a3a3' }}>Loading...</div>;

  return (
    <div className="page">
      <h1 style={{ fontSize: 'clamp(26px, 4vw, 40px)', fontWeight: 900, marginBottom: 8 }}>{t.newsTitle}</h1>
      <p style={{ color: '#a3a3a3', marginBottom: 36 }}>{t.latestUpdates}</p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
        {news.map(n => (
          <div key={n.id} style={{ background: '#171717', border: '1px solid #262626', borderRadius: 20, overflow: 'hidden' }}>
            {n.images?.[0] && (
              <img src={n.images[0].url} alt={title(n)} style={{ width: '100%', height: 'clamp(160px, 25vw, 240px)', objectFit: 'cover' }} />
            )}
            <div style={{ padding: 'clamp(16px, 3vw, 24px)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12, flexWrap: 'wrap', gap: 8 }}>
                <span style={{ background: '#f9731620', color: '#f97316', padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 600 }}>{n.category}</span>
                <span style={{ color: '#666', fontSize: 13 }}>{new Date(n.created_at || n.date).toLocaleDateString()}</span>
              </div>
              <h2 style={{ fontSize: 'clamp(16px, 2.5vw, 22px)', fontWeight: 800, marginBottom: 10, lineHeight: 1.3 }}>{title(n)}</h2>
              <p style={{ color: '#a3a3a3', fontSize: 14, lineHeight: 1.7, marginBottom: 16 }}>
                {content(n).length > 160 ? content(n).slice(0, 160) + '...' : content(n)}
              </p>
              <button onClick={() => setSelected(n)} style={{ background: '#f97316', color: '#000', border: 'none', padding: '9px 18px', borderRadius: 8, fontWeight: 700, fontSize: 14 }}>
                {t.readMore}
              </button>
            </div>
          </div>
        ))}
        {news.length === 0 && <p style={{ color: '#a3a3a3', textAlign: 'center' }}>{t.noNews}</p>}
      </div>

      {/* Modal */}
      {selected && (
        <div onClick={() => setSelected(null)} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 9999, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', padding: '0 0 0 0' }}>
          <div onClick={e => e.stopPropagation()} style={{ background: '#111', borderRadius: '20px 20px 0 0', width: '100%', maxWidth: 700, maxHeight: '90vh', overflowY: 'auto', padding: 'clamp(20px, 4vw, 32px)' }}>
            <button onClick={() => setSelected(null)} style={{ float: 'right', background: 'none', border: 'none', color: '#fff', fontSize: 24, cursor: 'pointer' }}>✕</button>
            <span style={{ background: '#f9731620', color: '#f97316', padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 600 }}>{selected.category}</span>
            <h2 style={{ fontSize: 'clamp(18px, 3vw, 26px)', fontWeight: 900, margin: '14px 0 8px', lineHeight: 1.3 }}>{title(selected)}</h2>
            <p style={{ color: '#666', fontSize: 13, marginBottom: 18 }}>{new Date(selected.created_at || selected.date).toLocaleDateString()}</p>
            {selected.images?.length > 0 && (
              <div style={{ display: 'flex', gap: 10, overflowX: 'auto', marginBottom: 18, paddingBottom: 4 }}>
                {selected.images.map(img => (
                  <img key={img.id} src={img.url} alt="" style={{ height: 160, borderRadius: 10, objectFit: 'cover', flexShrink: 0 }} />
                ))}
              </div>
            )}
            <p style={{ color: '#d4d4d4', fontSize: 15, lineHeight: 1.8 }}>{content(selected)}</p>
          </div>
        </div>
      )}
    </div>
  );
}
